      const mark = Object.assign(document.createElement("button"),{type:"button", className:"pbtn", textContent: T.suspects[n.id] ? "★ Suspect" : "☆ Mark"});
      mark.addEventListener("click", ()=>{ T.suspects[n.id] = !T.suspects[n.id]; renderJournalT(); });
