        const a = Math.sin(t*.9)*.7; g.fillStyle = "rgba(255,240,180,.18)"; g.beginPath(); g.moveTo(52,26); g.lineTo(52+Math.cos(a+1)*400, 26+Math.sin(a+1)*400); g.lineTo(52+Math.cos(a+1.25)*400, 26+Math.sin(a+1.25)*400); g.fill();
