  if (T.mode==="slasher" && T.spyE && !T.spyE.hidden && !T.spyE.dead) ents.push({e:T.spyE, L:T.spyE.look, spy:true});
  ents.sort((a,b)=>rposT(a.e)[1]-rposT(b.e)[1]);
