    if (me && pl.carrying){ const b = T.bodies.find(x=>x.id===pl.carrying), bn = b && byIdT(b.id); if (bn){ ctx.save(); ctx.translate(sx+8, sy-6); ctx.rotate(-Math.PI/2); drawPerson(ctx, -8, -8, bn.look, [0,1], 0, {blink:true}); ctx.restore(); } }
